{"content":"namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The key-verified raw-name override keys of <c>Lexicon/Resources/exact-overrides.json</c>, read from
/// the Fdc assembly's embedded resource — the same file the production override path consults (via
/// <c>SpecialCases</c>), so the census's <c>overrideKey</c> column cannot drift from it.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private readonly System.Collections.Frozen.FrozenSet<string> _keys;

	/// <summary>Loads the embedded <c>exact-overrides.json</c> key set.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(LetUsCook.Fdc.Lexicon.FdcNormalizer).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		using var doc = System.Text.Json.JsonDocument.Parse(reader.ReadToEnd());
		_keys = doc.RootElement.EnumerateObject().Select(e => e.Name).ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Number of keys in the table.</summary>
	public int Count => _keys.Count;

	/// <summary>Whether the normalized raw text is a key of <c>exact-overrides.json</c>.</summary>
	/// <param name="normalizedKey">The raw text normalized by <see cref="AutoWrongClassifier.NormalizeForOverrideKey"/>.</param>
	public bool Contains(string normalizedKey) => _keys.Contains(normalizedKey);
}
