{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on the two axes the P12.13 brief defines: the relation of
/// the accepted row to the key row (first matching rule wins) and the decision site. Every
/// normalisation, state mask, head term and singularisation call goes through the production
/// helpers (D-014) — nothing here re-implements matcher logic.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, the key row is Canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tier differs.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head and state agree, the tier agrees, and only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, or a field a rule needs is missing from the trace.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token production state calls (CA1861: no constant arrays as arguments).
	private readonly List<string> _singleToken = new(1);

	/// <summary>Creates the classifier over the production normalizer and the override key index.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// The state mask production applies to a token list: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// (ParseState words plus the salt/with/without rule) OR <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// (dry/bottled/kippered/cooking-participle words) — the same composition <c>FdcMatcher</c> feeds
	/// <c>StateAgrees</c>.
	/// </summary>
	/// <param name="tokens">Normalized tokens of one row description.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// The key head phrase: the key row's normalized tokens up to (excluding) the first token that
	/// production treats as a state or modifier word — <c>ModifierWords</c>, or a token the
	/// production state/satisfier extractors flag on their own. "Bread, crumbs, dry, grated, plain"
	/// yields <c>bread crumbs</c>; "Tomatoes, crushed, canned" yields <c>tomato</c>.
	/// </summary>
	/// <param name="tokens">Normalized tokens of the key row description.</param>
	/// <returns>The head phrase tokens, singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (IsStateOrModifierWord(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>
	/// Classifies one auto-wrong line. The first matching relation rule wins (brief §4 order 1–8);
	/// a rule whose input field is missing from the trace yields <see cref="Other"/> with
	/// <see cref="ClassificationResult.MissingField"/> naming it (brief §8).
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true &amp;&amp; correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var acceptedDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyTier = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var acceptedTier = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome == "accepted") ?? line.Atoms.FirstOrDefault();
		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = ClassifySite(atom);
		var overrideKey = site == SiteOverride ? (_overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty;

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			ParsedName = parsedName,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (site.Length == 0)
		{
			return result;
		}

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		result.KeyState = keyState.ToString();
		result.AcceptedState = acceptedState.ToString();

		var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedParsed = acceptedDesc.Length > 0 ? FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)) : null;
		var keyHead = SingularPhrase(keyParsed.HeadTerm);
		var acceptedHead = acceptedParsed is null ? [] : SingularPhrase(acceptedParsed.HeadTerm);
		result.KeyHead = string.Join(' ', keyHead);

		var parsedNameTokens = SingularPhrase(parsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		if (PackUnitRegex().IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (acceptedState & FoodState.Canned) == 0)
		{
			result.Relation = PackUnitState;
			return result;
		}

		if (keyPhrase.Count >= 2 && parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		if (acceptedParsed is null)
		{
			result.Relation = Other;
			result.MissingField = "actualDescriptions";
			return result;
		}

		if (keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase))
		{
			if (keyState != acceptedState)
			{
				result.Relation = StateMismatch;
				return result;
			}

			if (keyTier.Length == 0 || acceptedTier.Length == 0)
			{
				result.Relation = Other;
				result.MissingField = keyTier.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
				return result;
			}

			if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				result.Relation = RowChoiceTier;
				return result;
			}

			var keyQualifiers = SingularPhraseList(keyParsed.Qualifiers);
			var acceptedQualifiers = SingularPhraseList(acceptedParsed.Qualifiers);
			result.KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			result.AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
			result.Relation = SameHeadOtherQualifier;
			return result;
		}

		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// The decision site from the atom: <c>override</c>/<c>curated</c> by path, <c>reuse</c> when the
	/// ranker path reused a row, <c>ranker</c> otherwise. Empty when the path is none of the three.
	/// </summary>
	/// <param name="atom">The line's atom, or null.</param>
	/// <returns>The site, or empty.</returns>
	public static string ClassifySite(TraceAtom? atom)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path.ToLowerInvariant() switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty,
		};
	}

	/// <summary>
	/// Folds a raw line text the way the production override lookup does before the raw-key table:
	/// lower-cased, trimmed, content from the first <c>(</c> dropped (FdcMatcher's private
	/// <c>StripFromParenthesis</c> is a single <c>IndexOf</c> cut; the cut is applied here and the
	/// lookup itself is the production key set).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded text.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var paren = rawText.IndexOf('(', StringComparison.Ordinal);
		var cut = paren >= 0 ? rawText[..paren] : rawText;

#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override-lookup folding.
		return cut.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private bool IsStateOrModifierWord(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}
}
