{"content":"using System.Globalization;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads a HoldoutGate trace, classifies every auto-wrong line, and writes the TSV (stdout) plus the
/// relation × site summary (stderr). Refuses any trace whose records carry a set other than
/// <c>debug</c>/<c>batch</c> (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusRunnerDependencies dependencies,
	IOptions<AutoWrongCensusOptions> options) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly IAutoWrongCensusRunnerDependencies _dependencies = dependencies;
	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <summary>Exit codes.</summary>
	public const int ExitSuccess = 0;

	/// <summary>Exit code for a missing file, a refused set, or unusable arguments.</summary>
	public const int ExitFailure = 1;

	/// <inheritdoc />
	public Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			_dependencies.Error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			return Task.FromResult(ExitFailure);
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensusAsync(cancellationToken)
			: RunPairsAsync(cancellationToken);
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return ExitFailure;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		_dependencies.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");

		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;
		foreach (var line in autoWrong)
		{
			var result = _dependencies.Classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
			}

			results.Add(result);
			_dependencies.Output.WriteLine(TsvRow(result));
		}

		WriteSummary(_dependencies.Error, _options.TracePath, lines.Count, results);

		if (unknownSite > 0)
		{
			_dependencies.Error.WriteLine($"refused: {unknownSite} line(s) with an unknown atom path; the site is not one of reuse/ranker/override/curated");
			return ExitFailure;
		}

		return ExitSuccess;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return ExitFailure;
		}

		if (!File.Exists(_options.CensusTsvPath))
		{
			_dependencies.Error.WriteLine($"census TSV not found at '{_options.CensusTsvPath}'.");
			return ExitFailure;
		}

		var censusRows = ReadCensusRows(_options.CensusTsvPath);
		if (censusRows is null)
		{
			return ExitFailure;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		_dependencies.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		var missingInTrace = 0;
		foreach (var row in censusRows)
		{
			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				missingInTrace++;
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null ? string.Empty : string.Join(' ', _dependencies.Classifier.KeyHeadPhrase(_dependencies.Normalizer.NormalizeToTokens(atom.ParsedName)));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', _dependencies.Classifier.KeyHeadPhrase(_dependencies.Normalizer.NormalizeToTokens(keyDesc)));
			_dependencies.Output.WriteLine($"{Cell(line.HoldoutId)}\t{line.LineIndex}\t{Cell(parsedNameHead)}\t{Cell(keyHead)}\t{Cell(line.RawText)}");
			emitted++;
		}

		_dependencies.Error.WriteLine($"pairs: emitted={emitted} missingInTrace={missingInTrace}");
		return ExitSuccess;
	}

	private async Task<List<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		if (!File.Exists(path))
		{
			_dependencies.Error.WriteLine($"trace not found at '{path}'.");
			return null;
		}

		var lines = new List<TraceLine>();
		var sets = new HashSet<string>(StringComparer.Ordinal);
		await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			TraceLine? line;
			try
			{
				line = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
			}
			catch (JsonException ex)
			{
				_dependencies.Error.WriteLine($"refused: unparseable trace line in '{path}': {ex.Message}");
				return null;
			}

			if (line is null)
			{
				_dependencies.Error.WriteLine($"refused: empty trace record in '{path}'.");
				return null;
			}

			sets.Add(line.Set);
			lines.Add(line);
		}

		foreach (var set in sets)
		{
			if (set != "debug" && set != "batch")
			{
				_dependencies.Error.WriteLine($"refused: trace set '{set}' (D-029: this tool reads debug/batch traces only, never sealed).");
				return null;
			}
		}

		return lines;
	}

	private static List<CensusRow>? ReadCensusRows(string path)
	{
		var rows = new List<CensusRow>();
		var header = File.ReadLines(path).FirstOrDefault()?.Split('\t') ?? [];
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf.TryAdd(header[i], i);
		}

		foreach (var column in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(column))
			{
				return null;
			}
		}

		foreach (var raw in File.ReadLines(path).Skip(1))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			var cells = raw.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			var blocker = cells[indexOf["blocker"]];
			var route = cells[indexOf["route"]];
			if (blocker != "window" || (route != "compound" && route != "other"))
			{
				continue;
			}

			if (!int.TryParse(cells[indexOf["lineIndex"]], NumberStyles.Integer, CultureInfo.InvariantCulture, out var lineIndex))
			{
				continue;
			}

			rows.Add(new CensusRow(cells[indexOf["holdoutId"]], lineIndex));
		}

		return rows;
	}

	private static string TsvRow(ClassificationResult r) =>
		$"{Cell(r.HoldoutId)}\t{r.LineIndex}\t{Cell(r.Set)}\t{Cell(r.Relation)}\t{Cell(r.Site)}\t{Cell(r.OverrideKey)}\t{Cell(r.AcceptedTier)}\t{Cell(r.KeyTier)}\t{Cell(r.AcceptedState)}\t{Cell(r.KeyState)}\t{Cell(r.ParsedName)}\t{Cell(r.KeyHead)}\t{Cell(r.AcceptedDesc)}\t{Cell(r.KeyDesc)}\t{Cell(r.RawText)}";

	private static string Cell(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static void WriteSummary(System.IO.TextWriter error, string tracePath, int totalLines, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		error.WriteLine($"autoWrongCensus trace={tracePath} set={set} lines={totalLines} autoWrong={results.Count}");
		error.WriteLine("relation\tsite\tcount");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation, StringComparer.Ordinal).ThenBy(g => g.Key.Site, StringComparer.Ordinal))
		{
			error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		error.WriteLine($"other rate: {other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key, StringComparer.Ordinal);
		error.WriteLine(missing.Any()
			? "missing fields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}"))
			: "missing fields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			error.WriteLine($"override-site lines: {overrideLines.Count}, exact-overrides.json key hits: {overrideLines.Count(r => r.OverrideKey == "yes")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var checkedCount = 0;
			var shouldReuseFalse = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				if (line is null || string.IsNullOrEmpty(line.LinkedIngredientId))
				{
					continue;
				}

				checkedCount++;
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(line.ParsedName), line.LinkedIngredientId))
				{
					shouldReuseFalse++;
				}
			}

			error.WriteLine($"reuse-site lines: {reuseLines.Count}, ShouldReuse(parsedName, linkedIngredientId) false: {shouldReuseFalse}/{checkedCount}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			error.WriteLine($"row-choice-tier: key tier higher={keyHigher}, accepted tier higher={tierLines.Count - keyHigher}");
		}

		var qualifierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier).ToList();
		if (qualifierLines.Count > 0)
		{
			error.WriteLine("same-head-other-qualifier lines:");
			foreach (var r in qualifierLines)
			{
				error.WriteLine($"  {r.HoldoutId}#{r.LineIndex} key-only=[{string.Join(", ", r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(", ", r.AcceptedOnlyQualifiers ?? [])}]");
			}
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static CensusRow? FindLine(ClassificationResult r) => null;
}

/// <summary>One P12.7 blocker-census TSV row selected by the pairs subcommand.</summary>
public sealed record CensusRow(string HoldoutId, int LineIndex);
