{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Reads one HoldoutGate trace, classifies every auto-wrong line (<c>auto &amp;&amp; !correct</c>)
/// through <see cref="AutoWrongClassifier"/>, and writes the TSV plus the relation × site summary.
/// Refuses any trace whose records carry a <c>set</c> other than <c>debug</c>/<c>batch</c> (D-029).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		return _options.Command switch
		{
			CommandLineArgumentParser.CensusCommand => await RunCensusAsync(cancellationToken).ConfigureAwait(false),
			CommandLineArgumentParser.PairsCommand => await RunPairsAsync(cancellationToken).ConfigureAwait(false),
			_ => Fail("unusable arguments; usage: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>"),
		};
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		if (RefusedSet(lines) is { } refused)
		{
			return Fail($"refused: trace record set '{refused}' is not debug or batch (D-029)");
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		foreach (var line in autoWrong)
		{
			cancellationToken.ThrowIfCancellationRequested();
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				return Fail($"refused: unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' on {line.HoldoutId}#{line.LineIndex}");
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteSummary(results);
		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		if (RefusedSet(lines) is { } refused)
		{
			return Fail($"refused: trace record set '{refused}' is not debug or batch (D-029)");
		}

		var census = await ReadCensusTsvAsync(_options.CensusTsvPath).ConfigureAwait(false);
		if (census is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;
		var unmatched = 0;

		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var row in census)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var parsedNameHead = string.Join(' ', FoldName(line.Atoms.FirstOrDefault()?.ParsedName ?? string.Empty));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(new FdcNormalizer().NormalizeToTokens(keyDesc)));
			writers.Output.WriteLine($"{Sanitize(row.HoldoutId)}\t{row.LineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: emitted={emitted} unmatched={unmatched}");
		return 0;
	}

	private void WriteCensusTsv(List<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(),
				Sanitize(r.Set),
				r.Relation,
				r.Site,
				r.OverrideKey,
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				r.AcceptedState,
				r.KeyState,
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteSummary(List<ClassificationResult> results)
	{
		var sets = string.Join(",", results.Select(r => r.Set).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(s => s, StringComparer.Ordinal));
		writers.Error.WriteLine($"autoWrongCensus set={sets} tracedLines={results.Count}");

		writers.Error.WriteLine("relation\tsite\tcount");
		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation, StringComparer.Ordinal).ThenBy(g => g.Key.Site, StringComparer.Ordinal))
		{
			writers.Error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key, StringComparer.Ordinal);
		foreach (var group in missing)
		{
			writers.Error.WriteLine($"missingField {group.Key}={group.Count()}");
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			writers.Error.WriteLine($"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var shouldReuseFalse = 0;
			var checkedCount = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
				if (atom is null || string.IsNullOrEmpty(atom.LinkedIngredientId) || string.IsNullOrWhiteSpace(atom.ParsedName))
				{
					continue;
				}

				checkedCount++;
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					shouldReuseFalse++;
				}
			}

			writers.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {shouldReuseFalse}/{checkedCount}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			writers.Error.WriteLine($"row-choice-tier key higher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} accepted higher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");
		}

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(", ", r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(", ", r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult r)
	{
		// The runner classifies in trace order; the summary re-derives the atom from the same list.
		return _lastLine is { } l && l.HoldoutId == r.HoldoutId && l.LineIndex == r.LineIndex ? l : null;
	}

	private async Task<List<TraceLine>?> ReadTraceAsync(string path)
	{
		if (!File.Exists(path))
		{
			return Fail($"trace file not found: {path}");
		}

		var lines = new List<TraceLine>();
		await foreach (var line in File.ReadLinesAsync(path).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				return Fail($"trace file {path} is not valid JSONL: {ex.Message}");
			}
		}

		_lastLine = null;
		return lines;
	}

	private async Task<List<CensusRow>?> ReadCensusTsvAsync(string path)
	{
		if (!File.Exists(path))
		{
			return Fail($"census TSV not found: {path}");
		}

		var rows = new List<CensusRow>();
		var header = File.ReadLines(path).FirstOrDefault();
		if (string.IsNullOrWhiteSpace(header))
		{
			return Fail($"census TSV {path} has no header");
		}

		var columns = header.Split('\t').ToDictionary(c => c, c => 0, StringComparer.Ordinal);
		foreach (var (name, _) in columns)
		{
			columns[name] = Array.IndexOf(header.Split('\t'), name);
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!columns.ContainsKey(required))
			{
				return Fail($"census TSV {path} is missing column '{required}'");
			}
		}

		var first = true;
		foreach (var line in File.ReadLines(path))
		{
			if (first)
			{
				first = false;
				continue;
			}

			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			var cells = line.Split('\t');
			if (cells.Length < columns.Values.Max() + 1)
			{
				return Fail($"census TSV {path} row has {cells.Length} cells, expected {columns.Values.Max() + 1}");
			}

			rows.Add(new CensusRow
			{
				HoldoutId = cells[columns["holdoutId"]],
				LineIndex = int.Parse(cells[columns["lineIndex"]]),
				Blocker = cells[columns["blocker"]],
				Route = cells[columns["route"]],
			});
		}

		return rows;
	}

	private string? RefusedSet(List<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !line.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				return line.Set;
			}
		}

		return null;
	}

	private int Fail(string message)
	{
		writers.Error.WriteLine($"AutoWrongCensus: {message}");
		return 1;
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static IReadOnlyList<string> FoldName(string parsedName) =>
		Array.ConvertAll(new FdcNormalizer().NormalizeToTokens(parsedName).ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');
}
